import torch
import triton
import triton.language as tl

# Define a Triton kernel to compute Frobenius norm
@triton.jit
def frobenius_norm_kernel(X, norm, BLOCK_SIZE: tl.constexpr):
    pid = tl.program_id(0)
    x = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = x < X.shape[0] * X.shape[1]
    if mask.any():
        X_local = tl.load(X + x, mask=mask)
        norm_local = tl.sum(X_local * X_local, mask=mask)
        tl.atomic_add(norm, norm_local)

class ModelNew:
    def __init__(self, model, device='cuda'):
        self.model = model
        self.device = device

    def forward(self, x):
        x = x.to(self.device)
        norm = torch.zeros(1, dtype=x.dtype, device=self.device)
        blocks = (x.numel() + 255) // 256
        frobenius_norm_kernel[blocks, 256](x, norm, BLOCK_SIZE=256)
        return norm.sqrt()

# Example usage
class SimpleModel(torch.nn.Module):
    def __init__(self):
        super(SimpleModel, self).__init__()
        self.linear = torch.nn.Linear(10, 10)

    def forward(self, x):
        return self.linear(x)

model = SimpleModel()
model_new = ModelNew(model)
input_data = torch.randn(100, 10, device='cuda')
output = model_new.forward(input_data)
print(output)
